package com.lotusdistribuidora.app

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.Base64

object LotusBrand {
    private const val LOGO_JPEG_BASE64 =
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "" +
        "np9d3u5tdIZquCGN7XEcIDQcYGPMrX0fZKbTsl1t9C+UUftbp44HkFsRduWs22bnfCEIB6TsdHbpbtVsD5qm4Vrp55JsOJOcADbYAcgvTTFjpbLedQR0jpRDU1YqTC4jgje4e9wgDYHGUIRgsZ5oQhcgRQhCAEIQhT//2Q=="

    fun bitmap(): Bitmap? = try {
        val bytes = Base64.decode(LOGO_JPEG_BASE64, Base64.DEFAULT)
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
    } catch (_: Exception) {
        null
    }
}
